import sqlite3
import sys
import traceback

def safe_eval(expression_str):
    """Safely evaluate a Python expression with restricted builtins."""
    try:
        # Restricted globals for safety
        restricted_globals = {
            '__builtins__': {
                'int': int,
                'float': float,
                'str': str,
                'bool': bool,
                'list': list,
                'dict': dict,
                'tuple': tuple,
                'set': set,
                'len': len,
                'sum': sum,
                'min': min,
                'max': max,
                'abs': abs,
                'round': round,
                'range': range,
                'enumerate': enumerate,
                'zip': zip,
                'sorted': sorted,
                'reversed': reversed,
            }
        }

        # Empty locals
        restricted_locals = {}

        # Evaluate the expression
        result = eval(expression_str, restricted_globals, restricted_locals)
        return result, None
    except Exception as e:
        return None, str(e)

